    add.u32 %r7, %r7, %r5;                  // global oh
    shl.b32 %r8, %r1, 4;
    add.u32 %r8, %r8, %r6;                  // global ow
    setp.lt.u32 %p1, %r7, 55;
    setp.lt.u32 %p2, %r8, 55;
    and.pred %p3, %p1, %p2;                 // valid output thread
    mov.u32 %r9, smem_buf;                  // shared memory base byte address
